{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Tranexamic acid, a zwitterionic amino acid with a carboxylic acid, has absolute oral bioavailability of 27–46% in humans, consistently above the 20% threshold despite ionization and low passive permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "p-Aminobenzoic acid, an aromatic carboxylic acid, shows about 90% oral bioavailability in humans, demonstrating that aromatic carboxylic acids can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Salicylic acid, an aromatic carboxylic acid with a phenolic group, has near-complete oral bioavailability (92–97%) in humans, supporting high F for the query's aromatic acid motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Nicotinic acid, a heteroaromatic carboxylic acid, has about 90% systemic availability in humans, supporting high oral bioavailability for the query's heteroaromatic carboxylic acid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "4-Phenylbutyric acid, an aromatic carboxylic acid, has an absolute oral bioavailability of about 78% in humans, providing direct evidence that carboxylic-acid-containing molecules can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Setipiprant, a larger fused bicyclic carboxylic acid, has oral bioavailability of at least 50% in humans, supporting high F for the query's fused bicyclic carboxylic acid structure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable experimental analogues contain carboxylic acids and many are aromatic or heteroaromatic acids; their measured oral bioavailability values range from about 27% to complete absorption, all above the 20% threshold. The query's ionization liability is therefore not sufficient to predict low F, and the consistent experimental evidence strongly supports high oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query molecule.",
    "No specific information is available on first-pass metabolism, efflux transport, or formulation effects for the query.",
    "The query's low logD at intestinal pH may reduce absorption rate, but the threshold is modest and analogous acids still exceed it."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

